from fastapi import FastAPI, Request, Response
from fastapi.responses import JSONResponse
import lxml.etree as etree
import io
import logging

app = FastAPI(title="Document Processing Service", version="2.1.0")
logger = logging.getLogger("doc_processor")

# Configuration for XML processing
XML_MAX_SIZE = 10 * 1024 * 1024  # 10MB
ALLOWED_CONTENT_TYPES = ["application/xml", "text/xml", "application/soap+xml"]


def validate_content_type(content_type: str) -> bool:
    """Validate that the request content type is an allowed XML type."""
    if not content_type:
        return False
    base_type = content_type.split(";")[0].strip().lower()
    return base_type in ALLOWED_CONTENT_TYPES


def parse_xml_document(xml_bytes: bytes) -> dict:
    """Parse XML document and extract structured data.

    Uses lxml for performance with large documents.
    Note: DTD validation is enabled for schema-conformant documents.
    """
    parser = etree.XMLParser(
        resolve_entities=True,
        dtd_validation=False,
        load_dtd=True,
        no_network=False,
        huge_tree=False
    )

    try:
        tree = etree.parse(io.BytesIO(xml_bytes), parser)
        root = tree.getroot()

        # Extract document metadata
        result = {
            "root_tag": root.tag,
            "attributes": dict(root.attrib),
            "children_count": len(root),
            "text_content": root.text or "",
            "namespaces": dict(root.nsmap) if root.nsmap else {}
        }

        # Extract first-level children
        children = []
        for child in root:
            children.append({
                "tag": child.tag,
                "text": (child.text or "").strip(),
                "attributes": dict(child.attrib)
            })
        result["children"] = children

        return result
    except etree.XMLSyntaxError as e:
        raise ValueError(f"XML parsing error: {str(e)}")


@app.post("/api/v2/documents/parse")
async def parse_document(request: Request):
    """Parse and extract data from XML documents.

    Accepts XML payloads and returns structured JSON representation.
    Used by internal microservices for document ingestion pipeline.
    """
    content_type = request.headers.get("content-type", "")

    if not validate_content_type(content_type):
        return JSONResponse(
            status_code=415,
            content={"error": "Unsupported content type. Expected XML."}
        )

    body = await request.body()

    if len(body) == 0:
        return JSONResponse(
            status_code=400,
            content={"error": "Empty request body"}
        )

    if len(body) > XML_MAX_SIZE:
        return JSONResponse(
            status_code=413,
            content={"error": "Document exceeds maximum size"}
        )

    try:
        result = parse_xml_document(body)
        logger.info(f"Successfully parsed document with root tag: {result['root_tag']}")
        return JSONResponse(status_code=200, content={"status": "success", "data": result})
    except ValueError as e:
        return JSONResponse(
            status_code=422,
            content={"error": str(e)}
        )
    except Exception as e:
        logger.error(f"Unexpected error processing document: {str(e)}")
        return JSONResponse(
            status_code=500,
            content={"error": "Internal processing error"}
        )


@app.get("/health")
async def health_check():
    return {"status": "healthy", "service": "doc-processor"}


if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8080)
